package host

var settingsCommands = map[string]commandSpec{
	"config":                {words: []string{"config"}},
	"server_set":            {words: []string{"config"}, write: true, args: []argument{requiredOpt("addr", "--addr")}},
	"autosync_set":          {words: []string{"config"}, write: true, args: []argument{{key: "enabled", flag: "--autosync", kind: "bool", required: true}}},
	"cure_auto_set":         {words: []string{"config"}, write: true, args: []argument{{key: "enabled", flag: "--cure-auto", kind: "bool", required: true}}},
	"agent_config":          {words: []string{"agent-config"}},
	"agent_set":             {words: []string{"agent-config"}, write: true, args: []argument{requiredOpt("setting", "--set")}},
	"account_list":          {words: []string{"account", "list"}},
	"account_use":           {words: []string{"account", "use"}, host: true, write: true, args: []argument{pos("name")}},
	"migration_list":        {words: []string{"migrate"}, host: true},
	"migration_apply":       {words: []string{"migrate"}, host: true, write: true, args: []argument{requiredOpt("source", "--source"), requiredOpt("account", "--account")}},
	"login":                 {words: []string{"login", "--oauth"}, host: true, write: true},
	"logout":                {words: []string{"logout"}, host: true, write: true},
	"keygen":                {words: []string{"keygen"}, host: true, write: true},
	"keys_export":           {words: []string{"keys-export"}, host: true, write: true, args: []argument{requiredOpt("out", "--out")}},
	"space_list":            {words: []string{"space", "list"}},
	"space_create":          {words: []string{"space", "create"}, host: true, write: true, args: []argument{pos("name")}},
	"space_use":             {words: []string{"space", "use"}, host: true, write: true, args: []argument{pos("name")}},
	"space_join":            {words: []string{"space", "join"}, host: true, write: true, args: []argument{pos("code")}},
	"space_invite":          {words: []string{"space", "invite"}, write: true, args: []argument{opt("note", "--note"), flag("readonly", "--readonly")}},
	"space_members":         {words: []string{"space", "members"}, args: []argument{{key: "name", kind: "string"}}},
	"space_remove":          {words: []string{"space", "remove", "--yes"}, host: true, write: true, args: []argument{pos("name")}},
	"inject_targets":        {words: []string{"inject", "--targets"}, host: true},
	"inject_preview":        {words: []string{"inject", "--preview"}, host: true, args: []argument{requiredOpt("id", "--id"), flag("remove", "--remove")}},
	"inject_apply":          {words: []string{"inject"}, host: true, write: true, args: []argument{requiredOpt("id", "--id"), opt("revision", "--expected"), flag("remove", "--remove")}},
	"classification_config": {words: []string{"classify-config"}, host: true, args: []argument{choice("backend", "--backend", "ds", "jev")}},
	"classification_save":   {words: []string{"classify-config", "--set"}, host: true, write: true, args: []argument{choice("backend", "--backend", "ds", "jev"), opt("base", "--api-base"), opt("model", "--model")}},
}
